module tb_TopModule;
    logic a;
    logic b;
    logic sel_b1;
    logic sel_b2;
    logic out_assign;
    logic out_always;

    TopModule dut (
        .a(a),
        .b(b),
        .sel_b1(sel_b1),
        .sel_b2(sel_b2),
        .out_assign(out_assign),
        .out_always(out_always)
    );

    initial begin
        integer i;
        logic expected;

        for (i = 0; i < 16; i = i + 1) begin
            {a, b, sel_b1, sel_b2} = i[3:0];
            #1;
            expected = (sel_b1 && sel_b2) ? b : a;

            if (out_assign !== expected || out_always !== expected) begin
                $display("SELFFAIL: a=%b, b=%b, sel_b1=%b, sel_b2=%b | expected=%b, out_assign=%b, out_always=%b",
                         a, b, sel_b1, sel_b2, expected, out_assign, out_always);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
